DROP INDEX "atarasy_member"."one_blocking_member_statement";--> statement-breakpoint
CREATE UNIQUE INDEX "one_blocking_member_statement" ON "atarasy_member"."engine_rows" USING btree ("deployment",("value"::jsonb->>'offer'),(CASE WHEN "value"::jsonb->>'kind' IN ('digital_decision','digital_withdrawal') THEN COALESCE(("value"::jsonb->>'incarnation')::bigint,0) ELSE 0 END),(CASE WHEN "value"::jsonb->>'kind' = 'digital_withdrawal' THEN 'withdrawal' ELSE 'decision' END)) WHERE "atarasy_member"."engine_rows"."namespace" = 'member_operations' AND ("atarasy_member"."engine_rows"."value"::jsonb->>'state') IN ('prepared','dispatching','uncertain','committed');